mapper.select:
select p.p_title as ptitle, p.p_brand as pbrand, p.p_category as pcategory, p.p_type as ptype, o.o_main_img as omainimg,o.o_price as oprice, o.o_default as odefault, p.p_no as pno, o.o_quantity as oquantity from dc_product p, dc_product_option o where p.p_no=o.p_no and o.o_default='Y' and p.p_type like '%' || #{ptype} || '%'
and p.p_category = #{pcategory}
order by p.p_no desc

select p.p_title as ptitle, p.p_brand as pbrand, p.p_category as pcategory, p.p_type as ptype, o.o_no as ono, o.o_main_img as omainimg, o.o_price as oprice, o.o_default as odefault, p.p_no as pno, o.o_origin_price as ooriginprice, o.o_quantity as oquantity, o.o_type_size as otypesize, o.o_color as ocolor, i.img_no as imgno, i.img_url as imgurl, p.p_content as pcontent, i.img_sort as imgsort from dc_product p inner join dc_product_option o on p.p_no = o.p_no left join dc_product_detail_image i on p.p_no = i.p_no where p.p_no = #{p_no}
and o.o_no = #{o_no}
and (o.o_default = 'Y' or o.o_no = ( select min(o_no) from dc_product_option where p_no = p.p_no ))
order by i.img_sort asc

mapper.update:
update dc_product_option
set o_default = 'N'
where p_no = #{p_no}
